#include <bits/stdc++.h>
using namespace std;

struct CharacterPair {
    char chr;
    int value;
    int idx;
    bool operator<(const CharacterPair& other) const {
        return value < other.value;
    }
};

bool checkAntiPalindrome(const std::vector<char>& chArr) {
    int len = chArr.size();
    for (int i = 0; i < len / 2; i++) {
        if (chArr[i] == chArr[len - i - 1]) {
            return false;
        }
    }
    return true;
}

void swapChars(std::vector<char>& chArr, std::vector<int>& vals, int i) {
    std::swap(chArr[i], chArr[chArr.size() - i - 1]);
    std::swap(vals[i], vals[vals.size() - i - 1]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    cin.ignore();
    std::string s;
    getline(cin, s);
    s.erase(s.begin(), s.begin() + s.find_first_not_of(" \t\n\r\f\v")); // trim leading whitespace
    s.erase(s.find_last_not_of(" \t\n\r\f\v") + 1); // trim trailing whitespace
    std::vector<char> chArr(s.begin(), s.end());

    std::vector<int> vals(n);
    for (int i = 0; i < n; i++) {
        cin >> vals[i];
    }
    cin.ignore();

    std::vector<CharacterPair> mismatchChars;
    std::vector<CharacterPair> pairs;
    for (int i = 0; i < n / 2; i++) {
        if (vals[i] > vals[n - i - 1]) {
            swapChars(chArr, vals, i);
        }
        CharacterPair cp{chArr[i], vals[i], i};
        if (chArr[i] == chArr[n - i - 1]) {
            mismatchChars.push_back(cp);
        }
        pairs.push_back(cp);
    }
    std::sort(pairs.begin(), pairs.end());

    int diffSum = 0;
    if (!checkAntiPalindrome(chArr)) {
        if (mismatchChars.size() == 1) {
            CharacterPair wrong = mismatchChars[0];
            for (const auto& cp : pairs) {
                if (cp.chr != wrong.chr && chArr[n - cp.idx - 1] != wrong.chr) {
                    diffSum = wrong.value + cp.value;
                    break;
                }
            }
        } else if (mismatchChars.size() > 1) {
            std::unordered_map<char, int> countMap;
            for (const auto& cp : mismatchChars) {
                countMap[cp.chr]++;
            }
            int maxCount = 0;
            for (const auto& kv : countMap) {
                if (kv.second > maxCount) maxCount = kv.second;
            }
            std::vector<CharacterPair> appendList;
            while (maxCount * 2 > (int)mismatchChars.size() + (int)appendList.size()) {
                auto maxEntry = std::max_element(countMap.begin(), countMap.end(),
                    [](const std::pair<char,int>& a, const std::pair<char,int>& b) {
                        return a.second < b.second;
                    });
                char maxChar = maxEntry->first;
                for (const auto& cp : pairs) {
                    if (cp.chr != maxChar && chArr[n - cp.idx - 1] != maxChar &&
                        std::find(mismatchChars.begin(), mismatchChars.end(), cp) == mismatchChars.end() &&
                        std::find(appendList.begin(), appendList.end(), cp) == appendList.end()) {
                        appendList.push_back(cp);
                        break;
                    }
                }
                // Recompute maxCount
                countMap[maxChar]++;
                maxCount = 0;
                for (const auto& kv : countMap) {
                    if (kv.second > maxCount) maxCount = kv.second;
                }
            }
            int sumMismatch = 0;
            for (const auto& c : mismatchChars) sumMismatch += c.value;
            int sumAppend = 0;
            for (const auto& c : appendList) sumAppend += c.value;
            diffSum = sumMismatch + sumAppend;
        }
    }
    int totalSum = std::accumulate(vals.begin(), vals.end(), 0);
    std::cout << totalSum - diffSum << "\n";

    return 0;
}
